from 写入第二遍 import add
add('27_003',2,'16:9，武士被扣住的头在画面左侧近层，欧铂双角面盔与头肩在右后显出；镜头由手部短短后退，落幅保留左侧头部、上方扣指和右后完整角盔。','武士头被长指固定着，白眼在黑隙里猛地向后偏，身体只来得及短颤；镜头退开，原本被巨体遮住的后方露出欧铂的双角棱面盔。欧铂已经立在身后，颈肩稳定，扣头手沿原来的接触点保持控制，披风边缘只被风带开一点；武士喉间挤出一记吐不成字的惊哽，眼点僵住。','角盔与被控头部外侧是浅暖灰天空，晨光穿雾使后层均匀偏亮，余尘很薄。','暖白晨光沿黑甲角缘与面盔中棱留窄亮边，上方冷白漫射让盔面几何层次清楚，脸完全遮住。','惊吸气一短截，甲指在控制点很轻地摩擦，披风只留极低风擦，来者没有脚步落声。',ja=['っ？！'],tone='武士惊惧的无词短哽与倒抽气，标点不逐字朗读。',kind='mixed',phase='reaction',node={'叙事阶段':'双角面盔来者在背后揭晓','欧铂.揭晓':'头肩角盔已显出，姓名尚未由人物叫出','武士.状态':'头被扣住，惊惧失语'},meaning='先手后人的原格揭晓保留，武士白眼与来者双角头肩的前后关系不变。',characters=['鬼头武士','欧铂'])
add('28_001',5.5,'16:9，董白正面脸部近景居画面中央，青的垂头发束在左侧近层、搭肩手臂横过下缘；固定机位，圆眼与紧张半张嘴清楚。','董白把视线从武士身上抬到新出现的面盔，双眼再次骤睁，眉尖压向中间；她先短短问是谁，嘴张开露出一线齿。第二句出口时，眼珠从角盔上缘移到扣头的手，又迅速回到面盔；青的头仍软垂在她肩旁，董白肩线因承重压低，却没有放松托住的姿态，问完只剩紧盯。','两人发丝外是透雾的浅蓝灰云层，暖白晨光在上缘铺开，低处米灰薄尘极淡。','上方冷白柔光照亮眼睛，晨光在黑发轮廓添暖白亮条；青银发与董白脸部分层清楚。','董白吸气骤短，搭肩衣料维持受力细响，远处风声在两句之间露出。',ja=['…今度は誰？','どうやって、音もなく現れたの？'],tone='董白由震惊挤出第一问，第二句急着寻找解释，音量压住，末尾悬着。',kind='mixed',phase='reaction',node={'叙事阶段':'董白震惊来者无声出现','董白.位置':'仍架住青，视线朝欧铂','青.状态':'闭眼无回应'},meaning='董白圆眼紧眉与青仍搭肩的原格关系保留，两句惊问不伴随放人或出手。',characters=['董白','青'],card={'opening':'更强的来者在她未察觉时已经到位。','beats':['抬眼见面盔，第一问出口','扫扣头手再回面盔，追问如何出现'],'coupling':'头脸寻找解释，身体仍被同伴的重量牵在原地。','landing':'她扶着青紧盯来者，无法靠刚才的自信处理。'})
add('28_002',7,'16:9，欧铂正面角盔头肩近景居画面中央，武士头部一角留在左下近层，右侧胸肩旋纹与黑甲边缘可见；固定低机位，完整中棱与下栅在框内。','欧铂先把面盔朝被控的武士微微下倾，叫出他的名字；颈侧肌肉绷成两道稳定线，发声从遮面的下栅后低低透出。短停后，他把质问逐句压下，扣头的手在左侧画外维持同一高度；武士头角在近层短颤一下，欧铂头肩始终稳住，直到最后一字落下才极轻地收回下颌。','角盔与肩颈外侧只有浅暖灰天空、稀薄米灰雾与淡蓝灰云纹，近层头部遮住左下大半背景。','暖白晨光沿双角与盔面中棱形成窄亮边，冷白云光保留黑甲暗部层次，颈侧受石面少量中性补光。','低稳的人声从面栅后透出，甲指受力的细小低响在问句间短露，披风风声很轻。',ja=['亀頭武士。','お前たちには、彼女に手を出すなと、はっきり命じたはずだが。'],tone='欧铂先低声点名，短停后用明确而压低的质问追责，末尾稳重下沉。',kind='mixed',phase='state',node={'叙事阶段':'欧铂点名质问违令，持续扣头'},meaning='遮面角盔、厚颈与武士局部近层的原格构图保留，“她”只按原文代词，不替换人物名字。',characters=['欧铂','鬼头武士'],card={'opening':'欧铂已经控制目标，追问的是违令。','beats':['微下倾面盔低声点名','颈侧绷紧，稳定压下完整质问','末字后收下颌极小一截'],'coupling':'力量来自控制的稳定与停顿，遮面角色不添加可见嘴型或眼神。','landing':'武士必须回答，扣头接触尚未松。'})
